:root {
    --blue: #00a3e0;
    --red: #e4002b;
    --green: #64a70b;
    --darkBlue: #004a99;
    --magenta: #b70060;
    --purple: #781778;
    --brightGreen: #c9d200;
    --turquoise: #00aba4;
    --white: #ffffff;
    --black: #000000;
    --gray: #9d9d9d;
    --lightGray: #e3e3e3;
}

.table-secondary .table tbody td:nth-child(n + 4) {
