/* Search */

.search__bar,
.search__bar .search,
.search__bar input {
    position: absolute;
    margin: auto;
    top: 0;
    bottom: 0;
}

.search__bar {
    /* right: 6rem;
    width: 300px;
    height: 80px; */
}

.search__bar .search {
    right: 0;
    /* width: 40px;
    height: 40px; */
    background: transparent;
    border-radius: 50%;
    transition: all 1s;
    z-index: 4;
}

.search__bar .search:hover,
.search__bar input:hover {
    cursor: pointer;
}

.search__bar .search::before {
    content: "";
    position: absolute;
    margin: auto;
    top: 12px;
    right: 0;
    bottom: 0;
    left: 10px;
    width: 6px;
    height: 2px;
    background: white;
    transform: rotate(45deg);
    transition: all 0.5s;
}

.search__bar .search::after {
    content: "";
    position: absolute;
    margin: auto;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    border: 2px solid white;
    transition: all 0.5s;
}

.search__bar input {
    right: -27px;
    width: 40px;
    height: 40px;
    outline: none;
    border: none;
    border-bottom: 1px solid var(--white);
    background: transparent;
    color: white;
    text-shadow: 0 0 10px transparent;
    padding: 0 40px 0 14px;
    transition: all 1s;
    opacity: 0;
    z-index: 5;
    font-weight: 500;
    letter-spacing: 0.1em;
}

.search__bar input:focus {
    width: 300px;
    opacity: 1;
    cursor: text;
}

.search__bar input:focus ~ .search {
    background: transparent;
    z-index: 6;
}

.search__bar input:focus ~ .search::before,
.search__bar input:focus ~ .search::after {
    top: 0;
    left: 0;
    width: 12px;
}

.search__bar input:focus ~ .search::after {
    height: 2px;
    border: none;
    background: white;
    border-radius: 0%;
    transform: rotate(-45deg);
}

.search__bar input::placeholder {
    color: white;
    opacity: 0.5;
    font-weight: 400;
}


