/* Oil history timeline */

.timeline-oil {
    display: flex;
    margin: 0 auto;
    flex-wrap: wrap;
    flex-direction: column;
    max-width: 800px;
    position: relative;
}

.timeline-oil__content-title {
    font-weight: 500;
    font-size: 48px;
    margin: 0;
    transition: 0.4s;
    box-sizing: border-box;
    color: #fff;
    display: none;
}

.timeline-oil__content-desc {
    margin: 20px 0 0 0;
    box-sizing: border-box;
    color: rgba(255, 255, 255, 1);
}

.timeline-oil:before {
    position: absolute;
    left: 50%;
    width: 2px;
    height: 100%;
    margin-left: -1px;
    content: "";
    background: rgba(255, 255, 255, .07);
}

.timeline-oil-item {
    padding: 60px 0 40px 0;
    opacity: 0.3;
    filter: blur(2px);
    transition: 0.5s;
    box-sizing: border-box;
    width: calc(50% - 40px);
    display: flex;
    position: relative;
    transform: translateY(-120px);
}

.timeline-oil-item:before {
    content: attr(data-text);
    width: 100%;
    position: absolute;
    color: rgba(255, 255, 255, .7);
    font-size: 50px;
    border-left: 2px solid rgba(255, 255, 255, .7);
    top: 70%;
    margin-top: -5px;
    padding-left: 15px;
    opacity: 0;
    right: calc(-100% - 56px);
    font-weight: 500;
    line-height: 1;
}

.timeline-oil-item:nth-child(even) {
    align-self: flex-end;
}

.timeline-oil-item:nth-child(even):before {
    right: auto;
    text-align: right;
    left: calc(-100% - 56px);
    padding-left: 0;
    border-left: none;
    border-right: 2px solid rgba(255, 255, 255, .7);
    padding-right: 15px;
}

.timeline-oil-item--active {
    opacity: 1;
    /* transform: translateY(0); */
    filter: blur(0px);
}

@media only screen and (min-width: 992px) {
    .timeline-oil__content {
        transition: all .5s;
        padding-top: 60px;
    }

    .timeline-oil-item--active .timeline-oil__content {
        transform: translateX(-40px) scale(1.2);
    }

    .timeline-oil-item--active:nth-child(even) .timeline-oil__content {
        transform: translateX(40px) scale(1.2);
    }
}

.timeline-oil-item--active:before {
    top: 50%;
    transition: 0.3s all 0.2s;
    opacity: 1;
}

.timeline-oil-item--active .timeline-oil__content-title {
    margin: 10px 0 0 0;
}

.timeline-oil__img {
    max-width: 100%;
    box-shadow: 0 10px 15px rgba(0, 0, 0, .4);
    max-height: 300px;
}

.timeline-oil-container {
    width: 100%;
    position: relative;
    padding: 140px 0;
    /* transition: 0.3s ease 0s; */
    background-attachment: fixed;
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    /* transition: opacity .3s; */
}

.timeline-oil-container:before {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background: rgba(99, 99, 99, 0.8);
    content: "";
}

.timeline-oil-header {
    width: 100%;
    text-align: center;
    margin-bottom: 40px;
    position: relative;
    padding-bottom: 4rem;
}

.timeline-oil-header__title {
    color: #fff;
    margin: 0;
}

.timeline-oil-header__subtitle {
    color: rgba(255, 255, 255, .7);
    margin: 20px 0 0 0;
    font-weight: 400;
    font-style: italic;
}

@media only screen and (max-width: 991px) {
    .timeline-oil:before {
        left: 40px;
    }

    .timeline-oil__content-title {
        display: block;
    }

    .timeline-oil-item {
        align-self: baseline !important;
        width: 100%;
        padding: 80px 30px;
    }

    .timeline-oil-item:first-child {
        padding: 0px 30px 80px;
    }

    .timeline-oil-item:before {
        left: 10px !important;
        padding: 0 !important;
        top: 50px;
        text-align: center !important;
        width: 60px;
        border: none !important;
    }

    .timeline-oil-item:last-child {
        padding-bottom: 40px;
    }

    .timeline-oil-item:before {
        content: "";
    }

    .timeline-oil__content-desc {
        margin-top: 0;
    }

    .timeline-oil:before {
        background: transparent;
    }

    .timeline-oil-item--active {
        transform: translateY(0);
    }

    .timeline-oil-header {
        padding-bottom: 0;
    }
}


